        // Step 2: Check if owner has tokens
        uint256 ownerBalance = BossBaby(TARGET).balanceOf(owner);
        console.log("Owner balance:", ownerBalance);

        // Step 3: Also check contract balance (contract might have tokens from fees)
        uint256 contractBalance = BossBaby(TARGET).balanceOf(TARGET);
        console.log("Contract balance:", contractBalance);

